&reftitle.description;
public boolIo\Poll\Watcher::hasTriggered Io\Poll\Eventevent
Checks whether event is among the events returned by Io\Poll\Watcher::getTriggeredEvents.

&reftitle.parameters;


  event


    The event to check for.

&reftitle.returnvalues;

 Returns &true; if event was reported, &false;
 otherwise.

  &reftitle.examples;

   Io\Poll\Watcher::hasTriggered example


<?php
use Io\Poll\Context;
use Io\Poll\Event;
use Time\Duration;

[$reader, $writer] = stream_socket_pair(STREAM_PF_UNIX, STREAM_SOCK_STREAM, STREAM_IPPROTO_IP);

$context = new Context();
$context->add(new StreamPollHandle($reader), [Event::Read]);

fwrite($writer, 'ping');
fclose($writer);

foreach ($context->wait(Duration::fromSeconds(1)) as $watcher) {
    var_dump($watcher->hasTriggered(Event::Read));
    var_dump($watcher->hasTriggered(Event::Write));
    var_dump($watcher->hasTriggered(Event::HangUp));
}


   &example.outputs;


bool(true)
bool(false)
bool(true)
